import { useEffect, useState } from 'react';
import { Alert, Button, Empty, Select, Spin } from 'antd';
import { FileTableView } from '@1flowbase/files';
import type { BlockComponentProps } from '@1flowbase/block-sdk';

type FileTable = { id: string; code: string; title: string };

export default function FileManagementBlock({ ctx }: BlockComponentProps) {
  const [tables, setTables] = useState<FileTable[]>([]);
  const [selectedCode, setSelectedCode] = useState<string>();
  const [loading, setLoading] = useState(true);
  const [failed, setFailed] = useState(false);
  const [reload, setReload] = useState(0);

  useEffect(() => {
    let active = true;
    setLoading(true);
    setFailed(false);
    ctx.api.get<FileTable[]>('/api/console/settings/files/tables')
      .then((items) => {
        if (!active) return;
        setTables(items);
        setSelectedCode((current) => items.some((item) => item.code === current) ? current : items[0]?.code);
      })
      .catch(() => { if (active) setFailed(true); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [ctx.workspace.id, reload]);

  return (
    <div style={{ width: '100%', minWidth: 0 }}>
      {loading ? <Spin /> : failed ? (
        <Alert type="error" showIcon title="文件表加载失败" action={<Button onClick={() => setReload((value) => value + 1)}>重试</Button>} />
      ) : !selectedCode ? <Empty description="暂无可用文件表" /> : (
    <FileTableView
      key={`${ctx.workspace.id}:${selectedCode}`}
      fileTableCode={selectedCode}
      toolbarExtra={
        <Select
          aria-label="选择文件表"
          value={selectedCode}
          onChange={setSelectedCode}
          options={tables.map((table) => ({ value: table.code, label: table.title }))}
          style={{ width: 220, maxWidth: '100%', height: 44 }}
          showSearch={{ optionFilterProp: 'label' }}
        />
      }
    />
      )}
    </div>
  );
}
